"""Admin guide: known issues, frequently asked questions and getting support.
Known issues are the customer-visible part of doc/internal-dev-doc/known-gaps
in the depotex repo: remove an entry when its fix ships (and say so in the
changelog), add one when a limitation customers will meet is found."""
from engine import H, P, UL, TABLE, NOTE, WARN, STEPS, CODE, SHOT

SUPPORT_MAIL = "support@vectored.dev"

